/* Per-context module loading; no ScriptProcessor or main-thread audio callback. */
(()=>{const ready=new WeakMap(),loaded=new WeakSet();globalThis.PocketLoFi={prepare(c){if(!c.audioWorklet||typeof AudioWorkletNode==='undefined')return Promise.resolve(false);if(!ready.has(c))ready.set(c,c.audioWorklet.addModule('lofi-worklet.js?v=2').then(()=>{loaded.add(c);return true}).catch(e=>{ready.delete(c);throw e}));return ready.get(c)},create(c,input,output,settings){let disposed=false,node;const connect=()=>{if(disposed)return;node=new AudioWorkletNode(c,'pocket-lofi',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[2],processorOptions:settings});input.connect(node).connect(output)};const promise=loaded.has(c)?(connect(),Promise.resolve()):this.prepare(c).then(ok=>{if(disposed)return;if(!ok)throw Error('LoFi nécessite AudioWorklet : utilisez un navigateur récent en HTTPS.');connect()});promise.catch(e=>{if(typeof message==='function')message(e.message)});return {ready:promise,dispose(){disposed=true;if(node){try{input.disconnect(node)}catch{}node.disconnect();node.port.close()}}}}}})();
